using Microsoft.AspNetCore.Mvc; using Exercicio09_Veterinaria.Models; namespace Exercicio09_Veterinaria.Controllers; public class VeterinariaController:Controller { static List<Animal>A=new(){new Animal{Id=1,Nome="Rex",Especie="Cachorro",Idade=5,Dono="Carlos"}, new Animal{Id=2,Nome="Luna",Especie="Gato",Idade=3,Dono="Ana"}, new Animal{Id=3,Nome="Thor",Especie="Cachorro",Idade=7,Dono="Bruno"}, new Animal{Id=4,Nome="Mia",Especie="Gato",Idade=2,Dono="Carla"}, new Animal{Id=5,Nome="Bob",Especie="Cachorro",Idade=4,Dono="Diego"}, new Animal{Id=6,Nome="Nina",Especie="Gato",Idade=1,Dono="Eduarda"}, new Animal{Id=7,Nome="Max",Especie="Cachorro",Idade=6,Dono="Felipe"}, new Animal{Id=8,Nome="Mel",Especie="Gato",Idade=5,Dono="Gabriela"}}; public IActionResult Index()=>View(A); public IActionResult Cachorros()=>View("Index",A.Where(x=>x.Especie=="Cachorro").ToList()); public IActionResult Gatos()=>View("Index",A.Where(x=>x.Especie=="Gato").ToList()); }